{
  "source_poem_zh": "鸟雀呼晴，侵晓窥檐语。\n叶上初阳干宿雨。水面清圆，一一风荷举。",
  "critical_units": [
    {
      "id": "song_05_u1",
      "source_span": "鸟雀呼晴",
      "meaning": "鸟鸣被写成仿佛在呼唤晴天。"
    },
    {
      "id": "song_05_u2",
      "source_span": "侵晓窥檐语",
      "meaning": "拂晓时鸟雀在檐边活动鸣叫，“窥”带有拟人色彩。"
    },
    {
      "id": "song_05_u3",
      "source_span": "初阳干宿雨",
      "meaning": "早晨日光使叶上的夜雨渐干。"
    },
    {
      "id": "song_05_u4",
      "source_span": "一一风荷举",
      "meaning": "风中荷叶一片片举起，描写水面动态。"
    }
  ],
  "translations_to_score": [
    {
      "opaque_id": "x04eabe0513579c",
      "translation": "Birds call the fair weather, peering beneath the eaves at dawn.\nOn the leaves, the newborn sun dries the night’s rain.\nAcross the water, clear and round,\none by one, lotus leaves rise in the breeze.",
      "notes": []
    },
    {
      "opaque_id": "xf054abd37a5fe6",
      "translation": "Birds call for clear skies;\nat first light, they peer beneath the eaves and chatter.\nThe early sun dries last night's rain from the leaves.\nOn the water, fresh and round,\nlotus leaves rise, one by one, lifted by the wind.",
      "notes": []
    },
    {
      "opaque_id": "xe28dfb897d39dc",
      "translation": "Birds call for clear skies;\nat daybreak, they peer beneath the eaves and chatter.\nThe early sun dries last night’s rain upon the leaves.\nOn the water, pure and round,\nlotus leaves rise, one by one, in the breeze.",
      "notes": []
    },
    {
      "opaque_id": "xcf5c98297ebe83",
      "translation": "Birds call for clear skies;\nat first light they peep beneath the eaves and chatter.\nThe morning sun dries last night’s rain from the leaves.\nOn the water, fresh and round,\nlotus leaves lift, one by one, in the breeze.",
      "notes": []
    },
    {
      "opaque_id": "x63af98f21cecae",
      "translation": "Sparrows call the fair weather in,\npeering beneath the eaves at dawn, chattering.\nThe first sun dries the night's rain from the leaves;\non the clear, round water, each wind-blown lotus rises.",
      "notes": []
    },
    {
      "opaque_id": "x0ce8f40dc8aa55",
      "translation": "The birds call the fair skies in; at dawn’s first light, they peer beneath the eaves and chatter.\nThe newborn sun dries last night’s rain from the leaves. Clear and round, the water holds each lotus, lifted by the breeze.",
      "notes": []
    }
  ]
}

{
  "source_poem_zh": "自胡马窥江去后，废池乔木，犹厌言兵。\n渐黄昏，清角吹寒，都在空城。",
  "critical_units": [
    {
      "id": "song_06_u1",
      "source_span": "胡马窥江",
      "meaning": "以“胡马”代指来犯兵势，带有历史文化指涉。"
    },
    {
      "id": "song_06_u2",
      "source_span": "废池乔木",
      "meaning": "以残池和高木呈现战后城市景象。"
    },
    {
      "id": "song_06_u3",
      "source_span": "犹厌言兵",
      "meaning": "将废池乔木写成厌恶谈兵，形成拟人。"
    },
    {
      "id": "song_06_u4",
      "source_span": "清角吹寒",
      "meaning": "号角声与寒意相连，听觉引出体感和气氛。"
    }
  ],
  "translations_to_score": [
    {
      "opaque_id": "x17c100376da0c8",
      "translation": "Since enemy horsemen menaced the Yangtze and withdrew,\nthe ruined ponds and towering trees\nstill loathe all talk of war.\nDusk slowly gathers;\nclear horn calls breathe cold\nthrough the empty city.",
      "notes": []
    },
    {
      "opaque_id": "xed961260c278db",
      "translation": "Since the northern horses came probing across the river and departed, the ruined pools and towering trees still loathe to speak of war.\nAs dusk deepens, a mournful horn blows cold; all of it fills the empty city.",
      "notes": [
        "“Northern horses” refers to invading forces."
      ]
    },
    {
      "opaque_id": "x19f381a7d23fb2",
      "translation": "Since the northern warhorses came probing south and withdrew,\nEven ruined pools and towering trees still loathe to speak of war.\nDusk deepens; a cold horn sounds—\nAll resounds through the empty city.",
      "notes": []
    },
    {
      "opaque_id": "xefa917bcb64c36",
      "translation": "Since the northern cavalry withdrew after threatening the river,\nthe ruined ponds and towering trees\nstill loathe to speak of war.\nAs dusk slowly falls,\nthe clear horn blows its chill\nthroughout the empty city.",
      "notes": []
    },
    {
      "opaque_id": "xb5e1fbba2e2bb2",
      "translation": "Since the barbarian horsemen withdrew from the river,\nthe ruined pools and towering trees\nstill shrink from speaking of war.\n\nDusk deepens.\nCold horns sound,\nand all is silence in the empty city.",
      "notes": []
    },
    {
      "opaque_id": "x255c3f33c244d7",
      "translation": "Since the northern horses came to spy upon the river and withdrew,\nruined ponds and towering trees still loathe the mention of war.\nDusk slowly deepens; the mournful horn blows cold—\nall of it in an empty city.",
      "notes": []
    }
  ]
}

{
  "source_poem_zh": "纤云弄巧，
飞星传恨，
银汉迢迢暗度。
金风玉露一相逢，
便胜却人间无数。
柔情似水，
佳期如梦，
忍顾鹊桥归路。
两情若是久长时，
又岂在朝朝暮暮。",
  "critical_units": [
    {
      "id": "song_07_u1",
      "source_span": "纤云弄巧",
      "meaning": "云被写成有意变换巧妙形态。"
    },
    {
      "id": "song_07_u2",
      "source_span": "飞星传恨",
      "meaning": "星光被写成传递离愁的媒介。"
    },
    {
      "id": "song_07_u3",
      "source_span": "金风玉露一相逢",
      "meaning": "借秋日风露写一次珍贵相会，带有七夕文化意象。"
    },
    {
      "id": "song_07_u4",
      "source_span": "又岂在朝朝暮暮",
      "meaning": "由相聚景象转为判断情意不必以日日相守为条件。"
    }
  ],
  "translations_to_score": [
    {
      "opaque_id": "xc7dbb694b27517",
      "translation": "Fine clouds weave their delicate designs;
shooting stars carry longing across the sky.
The Milky Way stretches far— they cross in secret.
When golden wind meets jade-white dew,
one meeting surpasses countless earthly ones.
Their tenderness flows like water;
their long-awaited hour, a dream.
How can they bear to watch the magpie bridge lead home?
If two hearts remain steadfast through the years,
what need have they of dawn-to-dusk togetherness?",
      "notes": [
        "The poem alludes to the Cowherd and Weaver Girl, parted by the Milky Way and reunited once each year."
      ]
    },
    {
      "opaque_id": "x55636a103f3ad3",
      "translation": "Slender clouds weave their delicate designs;
shooting stars convey their grief.
Across the distant Silver River, they steal silently through.
When golden wind meets jade-like dew,
one meeting surpasses countless earthly ones.
Tenderness flows like water;
the long-awaited tryst is dreamlike.
How can they bear to gaze back at the magpie bridge, then turn home?
If two hearts remain steadfast forever,
what need have they of mornings and evenings side by side?",
      "notes": []
    },
    {
      "opaque_id": "x6d7ccc058ae254",
      "translation": "Fine clouds weave their art;
shooting stars bear longing.
In secret, across the vast Milky Way.
One meeting in golden wind and jade dew
surpasses countless meetings on earth.

Tenderness flows like water;
the hour of reunion is a dream.
How bear to look back
at the homeward path over the magpie bridge?
If love between two hearts endures,
why must they be together
every morning, every night?",
      "notes": [
        "The magpie bridge evokes Qixi, a traditional festival associated with lovers’ reunion."
      ]
    },
    {
      "opaque_id": "x099b5f1e69bae0",
      "translation": "Delicate clouds weave their graceful patterns;
shooting stars carry their longing,
as they cross the vast, dim Milky Way.
When autumn’s golden wind meets jade-like dew,
one meeting surpasses countless earthly ones.
Tender feelings flow like water;
the long-awaited tryst is dreamlike—
how can they bear to look upon the magpie bridge and depart?
If two hearts remain constant through the years,
what need is there to be together every day and night?",
      "notes": [
        "The poem invokes the legend of the Cowherd and Weaver Girl, lovers separated by the Milky Way and reunited once a year across a bridge of magpies."
      ]
    },
    {
      "opaque_id": "x15e558ae6e5e1a",
      "translation": "Slender clouds weave their art;
shooting stars convey their sorrow.
Across the vast Silver River, they meet in secret.
When autumn wind and jade dew bring them together,
one meeting outshines countless earthly joys.
Their tender love flows like water;
their cherished tryst, a dream.
How could they bear to look toward the magpie bridge,
the road that leads them home apart?
If two hearts can stay true for long,
what need is there to be together every dawn and dusk?",
      "notes": []
    },
    {
      "opaque_id": "xdc5bd13b80b927",
      "translation": "Delicate clouds weave their art;  
Falling stars carry longing across the Milky Way.  
Beneath the autumn wind and jade-bright dew, one meeting  
Outshines a thousand earthly gatherings.  

Tenderness flows like water;  
The cherished hour passes like a dream.  
How can we bear to look back at the bridge,  
Then turn and take the road home?  

If two hearts can love for all time,  
Must they be bound to share each dawn and dusk?",
      "notes": [
        "The bridge evokes the traditional Qixi meeting, while the lovers’ identities remain unstated."
      ]
    }
  ]
}

{
  "source_poem_zh": "莫听穿林打叶声，何妨吟啸且徐行。\n竹杖芒鞋轻胜马，谁怕？一蓑烟雨任平生。",
  "critical_units": [
    {
      "id": "song_08_u1",
      "source_span": "莫听穿林打叶声",
      "meaning": "劝说不必被雨声牵制，劝说对象未明确。"
    },
    {
      "id": "song_08_u2",
      "source_span": "何妨吟啸且徐行",
      "meaning": "提出从容行走的行动选择。"
    },
    {
