      ]
    },
    {
      "opaque_id": "xb526f64b34cd32",
      "translation": "Why should a man not gird himself with a curved Wu blade\nAnd reclaim the fifty prefectures beyond the mountain passes?\nGo up a moment to Lingyan Pavilion—\nWhich scholar there was made a marquis, lord of ten thousand households?",
      "notes": [
        "The Wu blade is a curved sword associated with martial valor.",
        "Lingyan Pavilion displayed portraits of meritorious statesmen and generals; ten thousand households denotes a marquis’s rich fief."
      ]
    },
    {
      "opaque_id": "x7e9d69b390e3ec",
      "translation": "Why should a man not gird himself with a Wu blade\nAnd win back fifty frontier lands?\nPray, climb awhile to Lingyan Hall—\nWhat scholar there was lord of ten thousand households?",
      "notes": [
        "The Wu blade is a curved sword associated with warriors. Lingyan Hall displayed portraits of meritorious Tang officials; ten thousand households signifies a richly endowed noble rank."
      ]
    },
    {
      "opaque_id": "xdcae0d177d70d0",
      "translation": "Why should a man not wear a Wu sword,\nTo reclaim the fifty prefectures beyond the passes?\nCome, sir, climb Lingyan Pavilion for a moment—\nWhich scholar has ever become a marquis of ten thousand households?",
      "notes": [
        "“Wu sword” refers to the famed weapons of ancient Wu.",
        "Lingyan Pavilion commemorated meritorious generals; the final line challenges scholars to seek military achievement."
      ]
    },
    {
      "opaque_id": "xc3b5ca208fb5cd",
      "translation": "Why not take up a Wu hook-sword, my brave young man,\nAnd win back the fifty prefectures beyond the passes?\nCome, climb the Portrait Pavilion awhile and look—\nWhich scholar has ever become a lord of ten thousand households?",
      "notes": []
    }
  ]
}

